        "text": "PCOS (polycystic ovary syndrome) is a hormonal condition, and for women trying to conceive its biggest effect is on ovulation. If you ovulate only now and then, you get fewer chances to become pregnant each year. That's usually why it takes longer, and it's also why treatment for PCOS-related infertility often works well once ovulation is back on track."
